/**
 * Service to create Enhanced Recurring Donation records from monthly-gift form data.
 *
 * Constraints satisfied:
 *  – At most 1 SOQL query (0 used) and 1 DML statement per invocation (≤200 requests).
 *  – All validation runs before the single DML; any failure aborts without partial data.
 *  – NPSP Enhanced Recurring Donations generates installment Opportunities automatically;
 *    this service never touches the Opportunity object.
 */
public with sharing class RecurringGiftService {

    // ── Exception type ──────────────────────────────────────────────────────
    public class RecurringGiftException extends Exception {}

    // ── Request DTO ─────────────────────────────────────────────────────────
    public class GiftRequest {
        public Id       contactId;
        public Decimal  amount;
        public Integer  dayOfMonth;      // 1-31  (31 = last day of month)
        public Date     startDate;
        public Integer  installments;    // null / 0 → open-ended
        public String   paymentMethod;   // 'Credit Card', 'ACH', 'Check'
    }

    // ── Public entry-point ──────────────────────────────────────────────────
    /**
     * Creates one Enhanced Recurring Donation per request.
     * Returns the new RD Ids in the same order as the incoming list.
     *
     * @param requests  list of GiftRequest; null or empty → empty list returned
     * @return          ordered list of newly created Recurring_Donation__c Ids
     * @throws RecurringGiftException  if any request fails validation
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {

        // 1. Null / empty guard
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // 2. Validate ALL requests BEFORE any DML
        //    (collect errors first so we can throw a single exception)
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];

            if (req.contactId == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': contactId is null.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(
                    'Request ' + i + ': amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Request ' + i + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(
                    'Request ' + i + ': startDate is null.');
            }
        }

        // 3. Build Recurring Donation records
        List<npe03__Recurring_Donation__c> rdList = new List<npe03__Recurring_Donation__c>(requests.size());

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor
            rd.npe03__Contact__c = req.contactId;

            // Amount per installment
            rd.npe03__Amount__c = req.amount;

            // Status
            rd.npe03__Status__c = 'Active';

            // Monthly recurrence
            rd.npe03__Recurrence_Type_Value__c = 'Monthly';
            rd.npe03__Recurrence_Installment_Frequency__c = 1;

            // Day of month – Enhanced RD "last day of month" option
            if (req.dayOfMonth == 31) {
                rd.npe03__Recurrence_Day_Value__c = 'Last Day';
            } else {
                rd.npe03__Recurrence_Day_Value__c = String.valueOf(req.dayOfMonth);
            }

            // Schedule start
            rd.npe03__Start_Date__c = req.startDate;

            // Installments: null or 0 → open-ended (leave field unset)
            //               otherwise → fixed-length with that many planned installments
            if (req.installments != null && req.installments > 0) {
                rd.npe03__Installments__c = req.installments;
            }

            // Payment method
            if (String.isNotBlank(req.paymentMethod)) {
                rd.npe03__Payment_Method__c = req.paymentMethod;
            }

            rdList.add(rd);
        }

        // 4. Single DML – bulk-safe for up to 200 (or more) records
        insert rdList;

        // 5. Return Ids in request order
        List<Id> newIds = new List<Id>(rdList.size());
        for (npe03__Recurring_Donation__c rd : rdList) {
            newIds.add(rd.Id);
        }
        return newIds;
    }
}
