public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all existing GAU allocations on the given Opportunity with one
     * percentage-based allocation per entry in percentByGauId.
     *
     * Percentage-based allocations (npsp__percent__c) ensure that when the
     * Opportunity Amount changes later, NPSP recalculates each allocation
     * amount automatically – no additional code is needed.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {

        // ── Validate map ──────────────────────────────────────────────
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'The percentByGauId map must not be null or empty.'
            );
        }

        // ── Validate individual percentages ───────────────────────────
        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Each percentage must be greater than 0. Found: ' + pct
                );
            }
            totalPercent += pct;
        }

        // ── Validate total ≤ 100 ─────────────────────────────────────
        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages sum to ' + totalPercent
                + ' which exceeds 100.'
            );
        }

        // ── Validate GAUs exist and are active ────────────────────────
        Set<Id> gauIds = new Set<Id>(percentByGauId.keySet());
        List<npsp__General_Accounting_Unit__c> gaos =
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ];

        if (gaos.size() != gauIds.size()) {
            throw new AllocationException(
                'One or more General Accounting Unit records were not found.'
            );
        }

        for (npsp__General_Accounting_Unit__c gau : gaos) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU "' + gau.Name + '" (' + gau.Id + ') is inactive.'
                );
            }
        }

        // ── Fetch the opportunity (needed for current amount) ─────────
        List<Opportunity> opps =
            [
                SELECT Id, Amount
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];

        if (opps.isEmpty()) {
            throw new AllocationException(
                'Opportunity not found: ' + opportunityId
            );
        }

        Decimal oppAmount = opps[0].Amount != null ? opps[0].Amount : 0;

        // ── Remove existing allocations for this opportunity ──────────
        List<npsp__Allocation__c> existing =
            [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
            ];

        if (!existing.isEmpty()) {
            delete existing;
        }

        // ── Build new percentage-based allocations ────────────────────
        List<npsp__Allocation__c> allocationsToInsert =
            new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            Decimal amount = oppAmount * pct / 100;

            allocationsToInsert.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c            = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__percent__c                 = pct,
                    npsp__amount__c                  = amount
                )
            );
        }

        // ── Insert and return ─────────────────────────────────────────
        insert allocationsToInsert;

        return allocationsToInsert;
    }
}
