/**
 * Trigger Action (TAF) – fires after Account insert.
 * Creates an onboarding Task (assigned to the Account owner) for every new
 * Account whose Type is "Customer - Direct" or "Customer - Channel".
 *
 * Bulk-safe: one DML for all qualifying Tasks; no DML when none qualify.
 */
public with sharing class TA_Account_CreateOnboardingTask implements ITriggerAction {

    public void doTriggerAction(
        List<SObject> newRecords,
        List<SObject> oldRecords,
        Map<Id, SObject> oldMap
    ) {
        // Only relevant on insert.
        if (!Trigger.isInsert) {
            return;
        }

        if (newRecords == null || newRecords.isEmpty()) {
            return;
        }

        Date onboardingDate = Date.today().addDays(7);

        List<Task> tasks = new List<Task>();

        for (SObject s : newRecords) {
            Account acct = (Account) s;

            if (
                acct.Type == 'Customer - Direct' ||
                acct.Type == 'Customer - Channel'
            ) {
                tasks.add(new Task(
                    Subject      = 'Onboard new customer',
                    WhatId       = acct.Id,
                    OwnerId      = acct.OwnerId,
                    ActivityDate = onboardingDate,
                    Status       = 'Not Started',
                    Priority     = 'Normal'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
