/**
 * Service class for bulk-importing contacts from a legacy system.
 *
 * <p>Uses the Trigger Actions Framework (TAF v0.3.4) bypass API to skip
 * the welcome-task action during the import DML while leaving every other
 * registered Contact trigger action (e.g. phone formatting) active.
 *
 * <p>The bypass is scoped to this single DML call; it is always removed
 * before the method returns so that later inserts in the same transaction
 * still receive their welcome tasks.
 */
public with sharing class ContactImportService {

    private static final String ACTION_CREATE_WELCOME_TASK = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied contacts in a single DML statement with the
     * "Send welcome pack" task creation suppressed.  All other Contact
     * trigger actions (including TA_Contact_FormatPhone) execute normally.
     *
     * @param contacts contacts to import; null/empty lists are a no-op
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // --- Bypass only the welcome-task action before the DML ---
        TriggerControl.disableAction(ACTION_CREATE_WELCOME_TASK);

        try {
            insert contacts;
        } finally {
            // Always re-enable so that any subsequent Contact inserts in
            // this same transaction (or unit-test context) still fire the
            // welcome-task action.
            TriggerControl.enableAction(ACTION_CREATE_WELCOME_TASK);
        }
    }
}
