/**
 * Bulk service to reassign ownership of Accounts and their Contacts.
 *
 * <ul>
 *   <li>Account trigger actions are bypassed via the Trigger Actions Framework
 *       so that expensive territory recalculation does not fire during the
 *       ownership change.</li>
 *   <li>Contact trigger actions run normally.</li>
 *   <li>Account trigger automation is restored in every code path (success or
 *       failure) via a {@code finally} block.</li>
 * </ul>
 */
public with sharing class AccountOwnershipService {

    /**
     * Sets {@code OwnerId} to {@code newOwnerId} on every Account in
     * {@code accountIds} and on every Contact whose AccountId is in that set.
     *
     * <p>Uses at most two SOQL queries and two DML statements regardless of
     * volume.  All-or-none semantics: if any record fails the entire
     * transaction is rolled back and the exception propagates to the caller.</p>
     *
     * @param accountIds  non-null set of Account Ids (up to 200)
     * @param newOwnerId  the Id of the new owner (User or Queue)
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {

        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // ── Bypass all Account trigger actions for this transaction ──────────
        TriggerHandlerSettings.bypassAllForSObject(Schema.SObjectType.Account);

        try {
            // ── Build Account records (no SOQL needed – we already have Ids) ─
            List<Account> accounts = new List<Account>();
            for (Id accountId : accountIds) {
                accounts.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }

            // ── Retrieve all Contacts under the given Accounts  (SOQL #1) ────
            List<Contact> contacts = [
                SELECT Id FROM Contact WHERE AccountId IN :accountIds
            ];

            for (Contact c : contacts) {
                c.OwnerId = newOwnerId;
            }

            // ── DML #1 – update Accounts (trigger actions bypassed) ──────────
            // All-or-none: any failure throws and rolls back the whole tx.
            update accounts;

            // ── DML #2 – update Contacts (trigger actions run normally) ──────
            if (!contacts.isEmpty()) {
                update contacts;
            }

        } finally {
            // ── Re-enable Account trigger automation for the rest of the
            //    transaction, whether the DML succeeded or threw. ─────────────
            TriggerHandlerSettings.unbypassAllForSObject(Schema.SObjectType.Account);
        }
    }
}
