public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerFramework.ITriggerAction {

    public void execute(
        TriggerFramework.TriggerContextType contextType,
        List<SObject> records,
        Map<Id, SObject> oldMap
    ) {
        // ---------------------------------------------------------------
        // 1. Identify contacts that need the duplicate-email check.
        //    • Skip records with no Account or no Email.
        //    • On update, skip records where neither Email nor AccountId changed.
        // ---------------------------------------------------------------
        List<Contact> toCheck = new List<Contact>();

        for (SObject sobj : records) {
            Contact c = (Contact) sobj;

            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            if (contextType == TriggerFramework.TriggerContextType.BEFORE_UPDATE
                && oldMap != null) {
                Contact old = (Contact) oldMap.get(c.Id);
                if (old != null
                    && old.Email == c.Email
                    && old.AccountId == c.AccountId) {
                    continue; // unrelated edit – leave legacy duplicates alone
                }
            }

            toCheck.add(c);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // ---------------------------------------------------------------
        // 2. Build collections for a single SOQL query.
        // ---------------------------------------------------------------
        Set<Id>    accountIds   = new Set<Id>();
        Set<String> lowerEmails = new Set<String>();

        for (Contact c : toCheck) {
            accountIds.add(c.AccountId);
            lowerEmails.add(c.Email.toLowerCase());
        }

        // ---------------------------------------------------------------
        // 3. One query – existing contacts on the same Account that share
        //    any of the same (case-insensitive) email addresses.
        // ---------------------------------------------------------------
        List<Contact> existing = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND LOWER(Email) IN :lowerEmails
        ];

        // ---------------------------------------------------------------
        // 4. Build a set of "AccountId|lowerEmail" keys found in the
        //    database, excluding the record being saved (self-reference).
        // ---------------------------------------------------------------
        Set<Id> processingIds = new Set<Id>();
        for (Contact c : toCheck) {
            if (c.Id != null) {
                processingIds.add(c.Id);
            }
        }

        Set<String> dbConflictKeys = new Set<String>();
        for (Contact ex : existing) {
            if (processingIds.contains(ex.Id)) {
                continue; // never conflict with self
            }
            dbConflictKeys.add(ex.AccountId + '|' + ex.Email.toLowerCase());
        }

        // ---------------------------------------------------------------
        // 5. Walk the batch in order.  The first record that carries a
        //    given Account+Email combination is accepted; every later
        //    record with the same combination (or one that collides with
        //    a row already in the DB) receives a record-level error.
        // ---------------------------------------------------------------
        Set<String> acceptedKeys = new Set<String>();

        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (dbConflictKeys.contains(key) || acceptedKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                acceptedKeys.add(key);
            }
        }
    }
}
