public with sharing class AccountTriggerRecord implements TriggerRecord {

    public Boolean isTriggerActionTriggered(TriggerContext context, TriggerAction action,
            Map<Id, SObject> newRecords, Map<Id, SObject> oldRecords) {

        String formula = action.Entry_Criteria_Formula__c;
        if (String.isBlank(formula)) {
            return true;
        }

        for (Id recId : newRecords.keySet()) {
            SObject newRec = newRecords.get(recId);
            SObject oldRec = (oldRecords != null) ? oldRecords.get(recId) : null;
            if (this.evaluateFormula(formula, newRec, oldRec)) {
                return true;
            }
        }
        return false;
    }

    private Boolean evaluateFormula(String formula, SObject newRec, SObject oldRec) {
        for (String condition : formula.split('&&')) {
            if (!this.evaluateCondition(condition.trim(), newRec, oldRec)) {
                return false;
            }
        }
        return true;
    }

    private Boolean evaluateCondition(String condition, SObject newRec, SObject oldRec) {
        String operator;
        Integer splitIdx;

        if (condition.contains('<>')) {
            operator = '<>';
            splitIdx = condition.indexOf('<>');
        } else if (condition.contains('!=')) {
            operator = '!=';
            splitIdx = condition.indexOf('!=');
        } else if (condition.contains('=')) {
            operator = '=';
            splitIdx = condition.indexOf('=');
        } else {
            return true;
        }

        String left  = condition.substring(0, splitIdx).trim();
        String right = condition.substring(splitIdx + operator.length()).trim();

        String leftVal  = this.resolveOperand(left,  newRec, oldRec);
        String rightVal = this.resolveOperand(right, newRec, oldRec);

        if (operator == '<>' || operator == '!=') {
            return leftVal != rightVal;
        }
        return leftVal == rightVal;
    }

    private String resolveOperand(String expr, SObject newRec, SObject oldRec) {
        // Strip TEXT() wrapper
        if (expr.startsWithIgnoreCase('TEXT(') && expr.endsWith(')')) {
            expr = expr.substring(5, expr.length() - 1).trim();
        }
        // Quoted literal
        if ((expr.startsWith('"') && expr.endsWith('"'))
                || (expr.startsWith('\'') && expr.endsWith('\''))) {
            return expr.substring(1, expr.length() - 1);
        }
        // Field reference – determine source record and field name
        String field;
        SObject rec;
        if (expr.startsWithIgnoreCase('Old.')) {
            field = expr.substring(4);
            rec   = oldRec;
        } else if (expr.startsWithIgnoreCase('New.')) {
            field = expr.substring(4);
            rec   = newRec;
        } else {
            field = expr;
            rec   = newRec;
        }
        if (rec == null) {
            return '';
        }
        try {
            Object val = rec.get(field);
            return (val == null) ? '' : String.valueOf(val);
        } catch (Exception e) {
            return '';
        }
    }
}
