public without sharing class TA_Case_RollupOpenCount implements TA_IAction {

    public void execute() {
        if (!Trigger.isAfter) return;

        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isUndelete) {
            // Trigger.new contains restored records; Trigger.old is null.
            // An undeleted case that was open will re-enter the count.
            for (Case c : (List<Case>) Trigger.new) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            }
        } else if (Trigger.isInsert) {
            // Only open cases affect the count. Closed cases inserted → no change.
            for (Case c : (List<Case>) Trigger.new) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Case c : (List<Case>) Trigger.new) {
                Case old = (Case) Trigger.oldMap.get(c.Id);
                // Only recalculate when IsClosed or AccountId actually changed.
                if (c.AccountId != old.AccountId || c.IsClosed != old.IsClosed) {
                    if (c.AccountId != null)      accountIds.add(c.AccountId);
                    if (old.AccountId != null)     accountIds.add(old.AccountId);
                }
            }
        } else if (Trigger.isDelete) {
            // Trigger.old contains the deleted records; Trigger.new is null.
            // Deleting an open case changes the count for its account.
            for (Case c : (List<Case>) Trigger.old) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) return;

        // ── SOQL 1: recalculate open-case count for every affected account ──
        // Runs AFTER the DML is committed, so the result reflects the
        // post-transaction state (deletes are gone, undeletes are back,
        // updates carry their new IsClosed / AccountId).
        Map<Id, Integer> openCountMap = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId, COUNT(Id) cnt
                FROM Case
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
                GROUP BY AccountId
            ]) {
            openCountMap.put((Id) ar.get('AccountId'),
                             (Integer) ar.get('cnt'));
        }

        // ── SOQL 2: fetch the Account rows we may need to update ──
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ];

        // ── build the update list ──
        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts) {
            Integer newCount = openCountMap.containsKey(acc.Id)
                ? openCountMap.get(acc.Id)
                : 0;   // last open case gone → 0, not null
            if (acc.FB_Open_Case_Count__c != newCount) {
                acc.FB_Open_Case_Count__c = newCount;
                toUpdate.add(acc);
            }
        }

        // ── DML 1 ──
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
