/**
 * After-update action (Order 10) that logs an audit Task whenever the
 * Opportunity Amount is changed by the user.
 *
 * Guards against the duplicate execution caused by TA_Opportunity_RoundAmount
 * (Order 20) which re-updates the same records in the same transaction.
 * The rounding is a consequence of the user's change, so at most ONE Task
 * is created per Opportunity per transaction.
 *
 * Bulk-safe: up to 200 Tasks inserted in a single DML.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /**
     * When true, this is the first after-update execution in the current
     * transaction (the user's DML).  Set to false immediately after the
     * first execution so that the re-entrant execution triggered by
     * TA_Opportunity_RoundAmount's "update toRound;" is a no-op.
     */
    private static Boolean isFirstExecution = true;

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        // Re-entrant execution from the rounding action's DML – skip entirely.
        if (!isFirstExecution) {
            return;
        }

        // Mark this as the first (and only) execution we will honour this transaction.
        // Must be set BEFORE any potential sub-DML so a re-entrant call sees it.
        isFirstExecution = false;

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Only log when Amount actually changed (handles nulls correctly).
            if (newOpp.Amount != oldOpp.Amount) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId  = newOpp.Id,
                    Status  = 'Completed'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
